import {
  DB_PATH,
  loadDb,
  saveDb,
  UserError,
  normalizeTags,
  isValidDate,
  todayLocal,
  type Task,
} from "./db.ts";

function parseFlags(argv: string[]): {
  positional: string[];
  flags: Record<string, string | true>;
} {
  const positional: string[] = [];
  const flags: Record<string, string | true> = {};
  let i = 0;
  while (i < argv.length) {
    const a = argv[i]!;
    if (a.startsWith("--")) {
      const name = a.slice(2);
      const eq = name.indexOf("=");
      if (eq >= 0) {
        flags[name.slice(0, eq)] = name.slice(eq + 1);
        i++;
        continue;
      }
      if (name === "tags" || name === "due" || name === "title" ||
          name === "status" || name === "tag" || name === "overdue") {
        i++;
        if (i >= argv.length) {
          throw new UserError(`--${name} requires a value`);
        }
        flags[name] = argv[i]!;
        i++;
        continue;
      }
      flags[name] = true;
      i++;
      continue;
    }
    positional.push(a);
    i++;
  }
  return { positional, flags };
}

function requireString(flags: Record<string, string | true>, key: string): string | undefined {
  const v = flags[key];
  if (v === undefined) return undefined;
  if (v === true) throw new UserError(`--${key} requires a value`);
  return v;
}

function cmdAdd(flags: Record<string, string | true>): Task {
  const title = requireString(flags, "title");
  if (title === undefined) throw new UserError("add requires --title");
  if (title.trim() === "") throw new UserError("title must not be empty");
  const tags = normalizeTags(requireString(flags, "tags"));
  const due = requireString(flags, "due");
  if (due !== undefined && !isValidDate(due)) {
    throw new UserError(`invalid due date: ${due}`);
  }
  const path = DB_PATH();
  const db = loadDb(path);
  const task: Task = {
    id: db.nextId,
    title,
    status: "open",
    createdAt: new Date().toISOString(),
    tags,
    ...(due !== undefined ? { due } : {}),
  };
  db.tasks.push(task);
  db.nextId += 1;
  saveDb(path, db);
  return task;
}

function cmdList(flags: Record<string, string | true>): Task[] {
  const status = requireString(flags, "status");
  const tag = requireString(flags, "tag");
  const overdue = requireString(flags, "overdue");
  if (status !== undefined && status !== "open" && status !== "done") {
    throw new UserError(`invalid status filter: ${status}`);
  }
  if (overdue !== undefined && !isValidDate(overdue)) {
    throw new UserError(`invalid overdue date: ${overdue}`);
  }
  const db = loadDb(DB_PATH());
  let result = db.tasks.slice().sort((a, b) => a.id - b.id);
  if (status) result = result.filter((t) => t.status === status);
  if (tag) {
    const norm = tag.trim().toLowerCase();
    result = result.filter((t) => t.tags.includes(norm));
  }
  if (overdue) {
    result = result.filter(
      (t) => t.status === "open" && t.due !== undefined && t.due < overdue
    );
  }
  return result;
}

function cmdDone(positional: string[]): Task {
  if (positional.length === 0) throw new UserError("done requires an ID");
  const id = parseId(positional[0]!);
  const path = DB_PATH();
  const db = loadDb(path);
  const task = db.tasks.find((t) => t.id === id);
  if (!task) throw new UserError(`task ${id} not found`);
  if (task.status !== "done") {
    task.status = "done";
    task.completedAt = new Date().toISOString();
    saveDb(path, db);
  }
  return task;
}

function cmdDelete(positional: string[]): { id: number; deleted: boolean } {
  if (positional.length === 0) throw new UserError("delete requires an ID");
  const id = parseId(positional[0]!);
  const path = DB_PATH();
  const db = loadDb(path);
  const idx = db.tasks.findIndex((t) => t.id === id);
  if (idx < 0) throw new UserError(`task ${id} not found`);
  db.tasks.splice(idx, 1);
  saveDb(path, db);
  return { id, deleted: true };
}

function cmdStats(): { total: number; open: number; done: number; overdue: number } {
  const db = loadDb(DB_PATH());
  const today = todayLocal();
  let open = 0;
  let done = 0;
  let overdue = 0;
  for (const t of db.tasks) {
    if (t.status === "done") {
      done++;
    } else {
      open++;
      if (t.due !== undefined && t.due < today) overdue++;
    }
  }
  return { total: db.tasks.length, open, done, overdue };
}

function parseId(s: string): number {
  const n = Number(s);
  if (!Number.isInteger(n) || n < 1) {
    throw new UserError(`invalid task id: ${s}`);
  }
  return n;
}

function main(argv: string[]): string {
  if (argv.length === 0) {
    throw new UserError("no command given; expected add|list|done|delete|stats");
  }
  const command = argv[0]!;
  const rest = argv.slice(1);
  if (command === "add") {
    const { flags } = parseFlags(rest);
    return JSON.stringify(cmdAdd(flags));
  }
  if (command === "list") {
    const { flags } = parseFlags(rest);
    return JSON.stringify(cmdList(flags));
  }
  if (command === "done") {
    const { positional } = parseFlags(rest);
    return JSON.stringify(cmdDone(positional));
  }
  if (command === "delete") {
    const { positional } = parseFlags(rest);
    return JSON.stringify(cmdDelete(positional));
  }
  if (command === "stats") {
    return JSON.stringify(cmdStats());
  }
  throw new UserError(`unknown command: ${command}`);
}

if (import.meta.main) {
  try {
    const out = main(process.argv.slice(2));
    console.log(out);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error(msg);
    process.exit(e instanceof UserError ? e.code : 1);
  }
}

