import { spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { assert, assertEquals } from "bun:test";

interface Task {
  id: number;
  title: string;
  status: "open" | "done";
  createdAt: string;
  completedAt?: string;
  tags: string[];
  due?: string;
}

function run(args: string[], dir: string, envFile: string): {
  stdout: string;
  stderr: string;
  code: number;
} {
  const env: Record<string, string> = { ...process.env } as Record<string, string>;
  env.TASKBOARD_FILE = envFile;
  const r = spawnSync(["bun", "run", "src/cli.ts", ...args], {
    cwd: dir,
    env,
    encoding: "utf8",
  });
  return {
    stdout: r.stdout ?? "",
    stderr: r.stderr ?? "",
    code: r.status ?? -1,
  };
}

let passed = 0;
function check(name: string, fn: () => void) {
  fn();
  passed++;
  console.error(`ok - ${name}`);
}

const projectDir = process.cwd();

check("add creates task with id and open status", () => {
  const dir = mkdtempSync(join(tmpdir(), "tb-"));
  const file = join(dir, ".taskboard.json");
  const r = run(["add", "--title", "Buy milk"], projectDir, file);
  assertEquals(r.code, 0, `stderr: ${r.stderr}`);
  const t: Task = JSON.parse(r.stdout);
  assertEquals(t.id, 1);
  assertEquals(t.status, "open");
  assertEquals(t.title, "Buy milk");
  assertEquals(t.tags, []);
  assert(typeof t.createdAt === "string");
  rmSync(dir, { recursive: true });
});

check("add with tags and due", () => {
  const dir = mkdtempSync(join(tmpdir(), "tb-"));
