function run(args: string[], dir: string, envFile: string): {
  stdout: string;
  stderr: string;
  code: number;
} {
  const env: Record<string, string> = { ...process.env } as Record<string, string>;
  env.TASKBOARD_FILE = envFile;
  const r = Bun.spawnSync({
    cmd: ["bun", "run", "src/cli.ts", ...args],
    cwd: dir,
    env,
    stdout: "pipe",
    stderr: "pipe",
  });
  const stdout = r.stdout ? new TextDecoder().decode(r.stdout as Uint8Array) : "";
  const stderr = r.stderr ? new TextDecoder().decode(r.stderr as Uint8Array) : "";
  return {
    stdout,
    stderr,
    code: r.exitCode ?? -1,
  };
}

