    return { nextId: 1, tasks: [] };
  }
  const text = readFileSync(path, "utf8");
  if (text.trim() === "") {
    throw new UserError(`database file is empty: ${path}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    throw new UserError(`malformed database: ${(e as Error).message}`);
  }
  if (!isDatabase(parsed)) {
    throw new UserError("database does not match expected schema");
  }
  return parsed;
}

